def sort_array(nums):
    nums = nums[:]
    for i in range(1, len(nums)):
        x, j = nums[i], i - 1
        while j >= 0 and nums[j] > x:
            nums[j + 1] = nums[j]
            j -= 1
        nums[j + 1] = x
    return nums

def sort_array(nums):
    if len(nums) <= 1:
        return nums[:]
    mid = len(nums) // 2
    left, right = sort_array(nums[:mid]), sort_array(nums[mid:])
    out, i, j = [], 0, 0
    while i < len(left) and j < len(right):
        if left[i] <= right[j]:              # <= keeps it stable
            out.append(left[i]); i += 1
        else:
            out.append(right[j]); j += 1
    return out + left[i:] + right[j:]

def sort_array(nums):
    nums = nums[:]

    def sift(i, n):
        while True:
            big, l, r = i, 2 * i + 1, 2 * i + 2
            if l < n and nums[l] > nums[big]:
                big = l
            if r < n and nums[r] > nums[big]:
                big = r
            if big == i:
                return
            nums[i], nums[big] = nums[big], nums[i]
            i = big

    n = len(nums)
    for i in range(n // 2 - 1, -1, -1):      # O(n) heapify
        sift(i, n)
    for end in range(n - 1, 0, -1):
        nums[0], nums[end] = nums[end], nums[0]
        sift(0, end)
    return nums

def sort_array(nums):
    nums, rng = nums[:], random.Random(0)

    def qs(lo, hi):
        while lo < hi:
            pivot = nums[rng.randint(lo, hi)]
            lt, i, gt = lo, lo, hi            # < pivot | == pivot | unseen | > pivot
            while i <= gt:
                if nums[i] < pivot:
                    nums[lt], nums[i] = nums[i], nums[lt]; lt += 1; i += 1
                elif nums[i] > pivot:
                    nums[gt], nums[i] = nums[i], nums[gt]; gt -= 1
                else:
                    i += 1
            if lt - lo < hi - gt:              # recurse on the smaller side
                qs(lo, lt - 1); lo = gt + 1
            else:
                qs(gt + 1, hi); hi = lt - 1

    qs(0, len(nums) - 1)
    return nums

def sort_array(nums):
    if not nums:
        return []
    lo = min(nums)
    counts = [0] * (max(nums) - lo + 1)
    for x in nums:
        counts[x - lo] += 1
    out = []
    for offset, c in enumerate(counts):
        out.extend([offset + lo] * c)
    return out
